const bell=new Audio('data:audio/wav;base64,'),broken=new Audio('data:audio/wav;base64,');
bell.volume=.3;broken.volume=.65;
export function paradoxSound(start){const a=start?bell:broken;a.currentTime=0;a.play().catch(()=>{});}
export function paradoxBanner(){const e=document.createElement('div');e.className='paradox-banner';e.setAttribute('role','status');e.textContent='オセロ将棋パラドックスにより、盤面が崩れてゆく！';document.body.append(e);return ()=>e.remove();}
